function Test-EntraCARequiredModules{[CmdletBinding()][OutputType([PSCustomObject])]param([Parameter(Mandatory)][array]$RequiredModules)foreach($req in $RequiredModules){$i=Get-Module -ListAvailable -Name $req.Name|Sort-Object Version -Descending|Select-Object -First 1;$is=$null -ne $i;$mv=$is -and ($i.Version -ge [version]$req.MinimumVersion);[PSCustomObject]@{Name=$req.Name;MinimumVersion=$req.MinimumVersion;InstalledVersion=if($is){$i.Version.ToString()}else{$null};IsInstalled=$is;MeetsVersion=$mv;Status=if(-not $is){"Missing"}elseif(-not $mv){"Outdated"}else{"OK"}}}}